import org.junit.Test;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.TextNode;

import static org.junit.Assert.*;

public class TextNodeTest {
    @Test
    public void textNodeConstructorTest() {
        TextNode tn = new TextNode("testing");
        assertNotNull(tn);
        assertEquals("testing", tn.text());
    }

    @Test
    public void nodeNameTest() {
        TextNode tn = new TextNode("testing");
        assertEquals("#text", tn.nodeName());
    }

    @Test
    public void textTest() {
        TextNode tn = new TextNode("testing");
        tn.text("changed");
        assertEquals("changed", tn.text());
    }

    @Test
    public void getWholeTextTest() {
        TextNode tn = new TextNode("testing");
        assertEquals("testing", tn.getWholeText());
    }

    @Test
    public void isBlankTest() {
        TextNode tn = new TextNode("");
        assertTrue(tn.isBlank());
    }

    public void isBlankFalseTest() {
        TextNode tn = new TextNode("test");
        assertFalse(tn.isBlank());
    }

    @Test
    public void splitTextTest() {
      TextNode tn = new TextNode("testing");
      TextNode split = tn.splitText(4);
      assertEquals("test", tn.getWholeText());
      assertEquals("ing", split.getWholeText());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        TextNode tn = new TextNode("testing");
        StringBuilder sb = new StringBuilder();
        tn.outerHtmlHead(sb, 0, new Document.OutputSettings());
        assertEquals("testing", sb.toString());
    }

    @Test
    public void outerHtmlTailTest() throws IOException {
        TextNode tn = new TextNode("testing");
        StringBuilder sb = new StringBuilder();
        tn.outerHtmlTail(sb, 0, new Document.OutputSettings());
        assertEquals("", sb.toString());
    }

    @Test
    public void toStringTest() {
        TextNode tn = new TextNode("testing");
        assertEquals("testing", tn.toString());
    }

    @Test
    public void cloneTest() {
        TextNode tn = new TextNode("testing");
        TextNode clone = tn.clone();
        assertNotSame(tn, clone);
        assertEquals(tn.text(), clone.text());
    }

    @Test
    public void createFromEncodedTest() {
        TextNode tn = TextNode.createFromEncoded("testing");
        assertNotNull(tn);
        assertEquals("testing", tn.text());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String normalised = TextNode.normaliseWhitespace("   testing   whitespace   ");
        assertEquals(" testing whitespace ", normalised);
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String stripped = TextNode.stripLeadingWhitespace("   testing");
        assertEquals("testing", stripped);
    }

    @Test
    public void lastCharIsWhitespaceTrueTest() {
        boolean isLastWhitespace = TextNode.lastCharIsWhitespace(new StringBuilder("testing "));
        assertTrue(isLastWhitespace);
    }

    @Test
    public void lastCharIsWhitespaceFalseTest() {
        boolean isLastWhitespace = TextNode.lastCharIsWhitespace(new StringBuilder("testing"));
        assertFalse(isLastWhitespace);
    }
}
